#!/usr/bin/env python3
"""Unit tests for the bitmask witness logic and BitCounters."""
import random, importlib.util
spec = importlib.util.spec_from_file_location('m', '/app/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

rng = random.Random(99)
# ---- BitCounters ----
for trial in range(200):
    nq = rng.randint(1, 64)
    ncls = rng.randint(1, 300)
    bc = m.BitCounters()
    naive = [0] * nq
    for _ in range(ncls):
        mask = 0
        for q in range(nq):
            if rng.random() < 0.3:
                mask |= 1 << q
                naive[q] += 1
        bc.add(mask)
    got = bc.counts(nq)
    assert got == naive, (trial, got, naive)
print('BitCounters ok')

# ---- witnesses logic (replicated from main.compute) ----
def witness_ok_bruteforce(masks_per_src, lits, W):
    """masks_per_src: list over sources of list over literals of bool lists."""
    for ms in masks_per_src:
        for i, li in enumerate(lits):
            cnt = 0
            for c in range(len(ms[0])):
                if ms[i][c] and not any(ms[j][c] for j in range(len(lits)) if j != i):
                    cnt += 1
            if cnt < W:
                return False
    return True

for trial in range(400):
    ns = rng.randint(1, 4)
    nlit = rng.randint(1, 6)
    nctx = rng.randint(1, 40)
    W = rng.randint(1, 3)
    # random literal masks per source
    lsrc = []
    srcmask = []
    for si in range(ns):
        ctxs = [c for c in range(nctx) if rng.random() < 0.8]
        sm = 0
        for c in ctxs:
            sm |= 1 << c
        srcmask.append(sm)
    for li in range(nlit):
        row = []
        full = 0
        for c in range(nctx):
            if rng.random() < 0.5:
                full |= 1 << c
        for si in range(ns):
            row.append(full & srcmask[si])
        lsrc.append(row)
    # brute force data: per source, per literal, bool per context
    bf = []
    for si in range(ns):
        bf.append([[bool(lsrc[li][si] >> c & 1) for c in range(nctx)] for li in range(nlit)])
    # candidate clause: subset of literals (distinct indices)
    for _ in range(10):
        k = rng.randint(1, min(4, nlit))
        lits = tuple(sorted(rng.sample(range(nlit), k)))
        want = witness_ok_bruteforce([ [bf[si][li] for li in lits] for si in range(ns)], lits, W)
        # replicate main's algorithm
        got = True
        if len(lits) == 1:
            for si in range(ns):
                if lsrc[lits[0]][si].bit_count() < W:
                    got = False
                    break
        else:
            for si in range(ns):
                sm = srcmask[si]
                ms = [lsrc[l][si] for l in lits]
                kk = len(lits)
                suf = [0] * (kk + 1)
                for i in range(kk - 1, -1, -1):
                    suf[i] = ms[i] | suf[i + 1]
                pre = 0
                for i in range(kk):
                    others = pre | suf[i + 1]
                    if (ms[i] & (sm ^ others)).bit_count() < W:
                        got = False
                        break
                    pre = pre | ms[i]
                if not got:
                    break
        assert got == want, (trial, lits, W, got, want)
print('witness logic ok')
